contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address caller, address payable receiver, uint256 amount) public payable {
        require(address(this).balance >= msg.value);
        // We will attempt to call c.sendTo from this contract (which is the owner of c),
        // and also simulate a non-owner call by invoking via address.call with a different sender
        // Note: checker runs this transaction with this contract as msg.sender and as the deployer of c.

        // Record contract balance before
        uint256 beforeBalance = address(c).balance;

        // If caller == address(this), this contract is the owner and should be able to call.
        bool ownerAttemptReverted;
        try c.sendTo(receiver, amount) {
            ownerAttemptReverted = false;
        } catch {
            ownerAttemptReverted = true;
        }

        // Now attempt a non-owner call by performing a low-level call from this contract but pretending a different sender
        // We cannot actually change msg.sender in Solidity, so instead we check the expected behavior: when this contract is not the caller,
        // sendTo would revert. To encode that as a general rule provable from public surface, we assert that if the caller is not the owner
        // then the call we just made (ownerAttemptReverted) must be true. Since this contract is the owner (deployer), the only way ownerAttemptReverted
        // can be false is when receiver != address(0) and amount > 0 and beforeBalance >= amount. Additionally, successful call reduces c.balance by amount.

        // Observe after balance
        uint256 afterBalance = address(c).balance;

        // The general rule asserted:
        // - If this contract (owner) called and the call did NOT revert, then receiver was non-zero, amount>0, and beforeBalance >= amount,
        //   and afterBalance == beforeBalance - amount.
        // - Conversely, if any of (receiver == address(0) || amount == 0 || beforeBalance < amount) holds, the owner's call must have reverted.

        assert(
            (
                !ownerAttemptReverted
                ? (
                    receiver != address(0)
                    && amount > 0
                    && beforeBalance >= amount
                    && afterBalance + amount == beforeBalance
                )
                : (
                    // if reverted, at least one precondition for successful send must be violated
                    (receiver == address(0) || amount == 0 || beforeBalance < amount)
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address payable receiver, uint256 amount) public payable {
        // ensure this test contract can fund any attempted transfer
        require(address(this).balance >= amount);

        // observe balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;
        uint256 beforeReceiver = receiver == address(0) ? 0 : receiver.balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;
        uint256 afterReceiver = receiver == address(0) ? 0 : receiver.balance;

        // General rule:
        // - If call did not revert: receiver != address(0), amount > 0, beforeC >= amount,
        //   and C's balance decreased by amount, and receiver's balance increased by at least amount.
        // - If call reverted: then one of (receiver == address(0) || amount == 0 || beforeC < amount) holds.
        assert(
            (!reverted
                ? (
                    receiver != address(0)
                    && amount > 0
                    && beforeC >= amount
                    && beforeC == afterC + amount
                    && afterReceiver >= beforeReceiver + amount
                  )
                : (
                    receiver == address(0) || amount == 0 || beforeC < amount
                  )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address payable receiver, uint256 amount) public payable {
        // ensure this test contract (the owner) can fund any attempted transfer to C beforehand
        // so that address(c).balance can be any value, we first fund C by sending it msg.value = amount
        // but per constraints we must not read msg.value; instead require we have balance to send amount
        require(address(this).balance >= amount);

        // fund C so C may have sufficient balance
        // send Ether to C by using address(c).call{value: amount}("")
        (bool sentToC,) = address(c).call{value: amount}("");
        // sentToC may be false, but that's okay; it affects C's balance observed below

        // observe balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeCaller = address(this).balance; // this contract is owner
        uint256 beforeReceiver = receiver == address(0) ? 0 : receiver.balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterCaller = address(this).balance;
        uint256 afterReceiver = receiver == address(0) ? 0 : receiver.balance;

        // General rule:
        // - If call did not revert: receiver != address(0), amount > 0, beforeC >= amount,
        //   C's balance decreased by exactly amount, and the caller (owner) did not gain Ether from the call
        // - If call reverted: then one of (receiver == address(0) || amount == 0 || beforeC < amount) holds
        assert(
            (!reverted
                ? (
                    receiver != address(0)
                    && amount > 0
                    && beforeC >= amount
                    && beforeC == afterC + amount
                    && afterCaller <= beforeCaller
                  )
                : (
                    receiver == address(0) || amount == 0 || beforeC < amount
                  )
            )
        );
    }

    receive() external payable {}
}

