contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sendTo with arbitrary receiver and amount. Must be payable to hold/send Ether if needed.
    function run(address receiver, uint256 amount) public payable {
        require(receiver != address(0));
        // ensure this contract has enough balance if it will call sendTo with amount
        if (address(this).balance < amount) return; // avoid doing anything if insufficient funds

        // record balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeReceiver = receiver.balance;

        bool reverted;
        try c.sendTo{value: 0}(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterReceiver = receiver.balance;

        // If call did not revert, then c's balance must have decreased by exactly amount
        // and receiver's balance must have increased by exactly amount.
        assert(reverted || (beforeC >= afterC && beforeC - afterC == amount && afterReceiver - beforeReceiver == amount));
    }

    // allow receiving Ether
    receive() external payable {}
}

